create table if not exists profile (id text primary key, sex text, age integer, height_cm numeric, activity_factor numeric, gym_met numeric, target_deficit numeric, updated_at timestamptz);
create table if not exists diet_plan (id bigint generated by default as identity primary key, meal_name text, description text, kcal numeric, protein numeric, carbs numeric, fat numeric);
create table if not exists meal_log (id bigint generated by default as identity primary key, eaten_at timestamptz, meal_name text, description text, kcal numeric, protein numeric, carbs numeric, fat numeric, source text);
create table if not exists manual_workout (id bigint generated by default as identity primary key, workout_date date, title text, duration_min numeric, intensity text, notes text);
create table if not exists manual_exercise (id bigint generated by default as identity primary key, workout_id bigint references manual_workout(id) on delete cascade, exercise text, muscle text, sets_count integer, reps integer, weight_kg numeric);
alter table profile disable row level security;
alter table diet_plan disable row level security;
alter table meal_log disable row level security;
alter table manual_workout disable row level security;
alter table manual_exercise disable row level security;
